"use strict";(globalThis.webpackChunkgrc||=[]).push([[46939],{4271(e){e.exports=JSON.parse('{"citeKey":"devarajan2021dlio","slug":"devarajan-2021-dlio-0272","title":"DLIO: A Data-Centric Benchmark for Scientific Deep Learning Applications","authors":["H. Devarajan","H. Zheng","A. Kougkas","X.-H. Sun","V. Vishwanath"],"venue":"The 2021 IEEE/ACM International Symposium in Cluster, Cloud, and Internet Computing (CCGrid\'21), May 17 - 20, 2021 Best paper award","type":"Conference","entryType":"inproceedings","date":"May, 2021","year":2021,"era":"iit","month":5,"doi":"10.1109/ccgrid51090.2021.00018","abstract":"Deep learning has been shown as a successful method for various tasks, and its popularity results in numerous open-source deep learning software tools. Deep learning has been applied to a broad spectrum of scientific domains such as cosmology, particle physics, computer vision, fusion, and astrophysics. Scientists have performed a great deal of work to optimize the computational performance of deep learning frameworks. However, the same cannot be said for I/O perfor- mance. As deep learning algorithms rely on big-data volume and variety to effectively train neural networks accurately, I/O is a significant bottleneck on large-scale distributed deep learning training. This study aims to provide a detailed investigation of the I/O behavior of various scientific deep learning workloads running on the Theta supercomputer at Argonne Leadership Computing Facility. In this paper, we present DLIO, a novel representative benchmark suite built based on the I/O profiling of the selected workloads. DLIO can be utilized to accurately emulate the I/O behavior of modern scientific deep learning applications. Using DLIO, application developers and system software solution architects can identify potential I/O bottlenecks in their applications and guide optimizations to boost the I/O performance leading to lower training times by up to 6.7x.","hasAbstract":true,"lede":"We present DLIO, a novel representative benchmark suite built based on the I/O profiling of the selected workloads.","links":{"pdf":"https://grc.iit.edu/papers/2021/devarajan-2021-dlio-0272.pdf","video":"https://youtu.be/_rRhQBaHVs8"},"tags":["Deep Learning","Scientific Applications","Representative","Benchmark","Data-Intensive","I/O","Characterization","TensorFlow","Data Pipeline","Hermes"],"_projectIds":["hermes","iris"],"grcSelected":false,"grcAwards":"Best Paper Award (First Prize)","status":"published","visibility":"public","projectIds":["deepio","hermes","iris"],"memberAuthors":["devarajan-hariharan","zheng-huihuo","kougkas-anthony","sun-xian-he","vishwanath-venkat"],"funding":[{"agency":"NSF","award":"OAC-1835764","projectId":"hermes"},{"agency":"NSF","award":"CSR-1814872","projectId":"iris"},{"agency":"ANL","award":"DE-AC02-06CH11357"}]}')}}]);